package org.example;

public class App {

    public static void main(String[] args) {
//        1. Estação do ano. Faça um programa que leia do teclado um número inteiro que representa o dia, e
//        uma string que representa o mês. Por fim, imprima na tela a estação do ano correspondente aqui no
//        Brasil.

//        Entre com o dia: 21
//        Entre com o mês: março
//        # Saída:
//        Outono

        int dia = Integer.parseInt(IO.readln("Entre com seu dia de Aniversário: "));
        String mes = IO.readln("Entre com o seu mês de nascimento: ");

        switch (mes.toLowerCase()){
            case "dezembro", "janeiro", "fevereiro" -> IO.println("Verão");
            case "março", "abril", "maio" -> IO.println("Outono");
            case "junho", "julho", "agosto" -> IO.println("Inverno");
            case "setembro", "outubro", "novembro" -> IO.println("Primavera");
        }
    }
}
